export interface Frontmatter {
  title: string;
  date?: string;
  tags?: string[];
  draft?: boolean;
  [key: string]: unknown;
}

export interface Page {
  frontmatter: Frontmatter;
  content: string;
  html: string;
  slug: string;
  sourcePath: string;
}

export interface SiteConfig {
  src: string;
  tmpl: string;
  out: string;
  port: number;
  baseUrl: string;
  title: string;
  description: string;
}

import { readFile } from "node:fs/promises";
import { basename, extname } from "node:path";
import matter from "gray-matter";
import type { Frontmatter, Page } from "./types.js";

export async function parseFile(path: string): Promise<Page | null> {
  const raw = await readFile(path, "utf-8");
  const { data, content } = matter(raw);
  const fm = data as Frontmatter;
  if (fm.draft) return null;
  const slug = basename(path, extname(path));
  return { frontmatter: fm, content, html: "", slug, sourcePath: path };
}

export function parseString(md: string): { data: Frontmatter; content: string } {
  const { data, content } = matter(md);
  return { data: data as Frontmatter, content };
}

import { readFile, readdir } from "node:fs/promises";
import { join, extname } from "node:path";
import { marked } from "marked";
import { markedHighlight } from "marked-highlight";
import hljs from "highlight.js";
import Handlebars from "handlebars";

marked.use(
  markedHighlight({
    langPrefix: "hljs language-",
    highlight(code: string, lang: string) {
      if (lang && hljs.getLanguage(lang)) {
        return hljs.highlight(code, { language: lang }).value;
      }
      return code;
    },
  }),
);

interface TemplateEntry {
  name: string;
  fn: HandlebarsTemplateDelegate;
}

export interface LoadedTemplates {
  layout: HandlebarsTemplateDelegate | null;
  templates: Map<string, HandlebarsTemplateDelegate>;
  partials: Map<string, HandlebarsTemplateDelegate>;
}

async function compileDir(dir: string): Promise<TemplateEntry[]> {
  const entries: TemplateEntry[] = [];
  const files = await readdir(dir).catch(() => [] as string[]);
  for (const f of files) {
    const full = join(dir, f);
    if (!f.endsWith(".hbs") && !f.endsWith(".handlebars")) continue;
    const src = await readFile(full, "utf-8");
    entries.push({ name: f.replace(/\.(hbs|handlebars)$/, ""), fn: Handlebars.compile(src) });
  }
  return entries;
}

export async function loadTemplates(tmplDir: string): Promise<LoadedTemplates> {
  const [templates, partials] = await Promise.all([
    compileDir(tmplDir),
    compileDir(join(tmplDir, "partials")),
  ]);

  let layout: HandlebarsTemplateDelegate | null = null;
  const tmap = new Map<string, HandlebarsTemplateDelegate>();

  for (const t of templates) {
    if (t.name === "layout") {
      layout = t.fn;
    } else {
      tmap.set(t.name, t.fn);
    }
  }

  const pmap = new Map<string, HandlebarsTemplateDelegate>();
  for (const p of partials) {
    Handlebars.registerPartial(p.name, p.fn);
    pmap.set(p.name, p.fn);
  }

  return { layout, templates: tmap, partials: pmap };
}

export function renderMarkdown(md: string): string {
  return marked.parse(md, { async: false }) as string;
}

export function renderTemplate(
  templates: LoadedTemplates,
  templateName: string,
  data: Record<string, unknown>,
): string {
  const t = templates.templates.get(templateName);
  if (!t) throw new Error(`Template "${templateName}" not found`);
  const body = t(data);
  if (templates.layout) {
    return templates.layout({ ...data, body });
  }
  return body;
}

import { writeFile } from "node:fs/promises";
import { join } from "node:path";
import type { Page, SiteConfig } from "./types.js";

function escapeXml(s: string): string {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

function rfc822Date(d: string): string {
  return new Date(d).toUTCString();
}

export async function generateRss(pages: Page[], config: SiteConfig): Promise<void> {
  const items = pages
    .filter((p) => !p.frontmatter.draft)
    .sort((a, b) => {
      const da = a.frontmatter.date ? new Date(a.frontmatter.date).getTime() : 0;
      const db = b.frontmatter.date ? new Date(b.frontmatter.date).getTime() : 0;
      return db - da;
    })
    .slice(0, 20)
    .map((p) => {
      const url = `${config.baseUrl}/${p.slug}.html`;
      return `    <item>
      <title>${escapeXml(p.frontmatter.title)}</title>
      <link>${escapeXml(url)}</link>
      <guid isPermaLink="true">${escapeXml(url)}</guid>
      <description>${escapeXml(p.html.slice(0, 300))}</description>
      ${p.frontmatter.date ? `<pubDate>${rfc822Date(p.frontmatter.date)}</pubDate>` : ""}
      <content:encoded><![CDATA[${p.html}]]></content:encoded>
    </item>`;
    })
    .join("\n");

  const feed = `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:content="http://purl.org/rss/1.0/modules/content/" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>${escapeXml(config.title)}</title>
    <link>${escapeXml(config.baseUrl)}</link>
    <description>${escapeXml(config.description)}</description>
    <atom:link href="${escapeXml(config.baseUrl)}/rss.xml" rel="self" type="application/rss+xml"/>
    <lastBuildDate>${rfc822Date(new Date().toISOString())}</lastBuildDate>
${items}
  </channel>
</rss>`;

  await writeFile(join(config.out, "rss.xml"), feed, "utf-8");
}

import { readdir, mkdir, writeFile, copyFile, stat } from "node:fs/promises";
import { join, extname, relative, dirname } from "node:path";
import { glob } from "./glob.js";
import { parseFile } from "./parser.js";
import { loadTemplates, renderMarkdown, renderTemplate, type LoadedTemplates } from "./renderer.js";
import { generateRss } from "./rss.js";
import type { Page, SiteConfig } from "./types.js";

async function ensureDir(dir: string): Promise<void> {
  await mkdir(dir, { recursive: true });
}

async function copyAssets(src: string, out: string): Promise<void> {
  const entries = await readdir(src, { withFileTypes: true }).catch(() => [] as never[]);
  for (const e of entries as { name: string; isDirectory(): boolean }[]) {
    const sp = join(src, e.name);
    const dp = join(out, e.name);
    if (e.isDirectory()) {
      if (e.name === "templates" || e.name.startsWith(".")) continue;
      await ensureDir(dp);
      await copyAssets(sp, dp);
    } else {
      if (e.name.endsWith(".md")) continue;
      await ensureDir(dirname(dp));
      await copyFile(sp, dp);
    }
  }
}

async function collectMarkdown(dir: string): Promise<string[]> {
  const files: string[] = [];
  const entries = await readdir(dir, { withFileTypes: true }).catch(() => [] as never[]);
  for (const e of entries as { name: string; isDirectory(): boolean }[]) {
    const full = join(dir, e.name);
    if (e.isDirectory()) {
      const nested = await collectMarkdown(full);
      files.push(...nested);
    } else if (e.name.endsWith(".md")) {
      files.push(full);
    }
  }
  return files;
}

function buildTagIndex(pages: Page[]): Map<string, Page[]> {
  const index = new Map<string, Page[]>();
  for (const page of pages) {
    const tags = page.frontmatter.tags ?? [];
    for (const tag of tags) {
      const list = index.get(tag) ?? [];
      list.push(page);
      index.set(tag, list);
    }
  }
  return index;
}

export async function generate(config: SiteConfig): Promise<void> {
  await ensureDir(config.out);

  const templates = await loadTemplates(config.tmpl);

  const mdFiles = await collectMarkdown(config.src);
  const pages: Page[] = [];

  for (const f of mdFiles) {
    const page = await parseFile(f);
    if (!page) continue;
    page.html = renderMarkdown(page.content);
    pages.push(page);
  }

  const published = pages.filter((p) => !p.frontmatter.draft).sort((a, b) => {
    const da = a.frontmatter.date ? new Date(a.frontmatter.date).getTime() : 0;
    const db = b.frontmatter.date ? new Date(b.frontmatter.date).getTime() : 0;
    return db - da;
  });

  const postPagesSub = ensureDir(join(config.out, "posts"));
  const tagDirSub = ensureDir(join(config.out, "tags"));

  const pageJobs = pages.map(async (page) => {
    const html = renderTemplate(templates, "post", {
      title: page.frontmatter.title,
      date: page.frontmatter.date ?? "",
      tags: page.frontmatter.tags ?? [],
      content: page.html,
      site: config,
      pages: published,
      page,
    });
    await writeFile(join(config.out, `${page.slug}.html`), html, "utf-8");
  });

  const indexJob = writeFile(
    join(config.out, "index.html"),
    renderTemplate(templates, "index", {
      title: config.title,
      pages: published,
      site: config,
    }),
    "utf-8",
  );

  const tagIndex = buildTagIndex(published);
  const tagJobs = [...tagIndex.entries()].map(async ([tag, taggedPages]) => {
    const html = renderTemplate(templates, "tag", {
      tag,
      pages: taggedPages,
      site: config,
      allTags: [...tagIndex.keys()],
    });
    await writeFile(join(config.out, "tags", `${tag}.html`), html, "utf-8");
  });

  const rssJob = generateRss(published, config);
  const assetsJob = copyAssets(config.src, config.out);

  await Promise.all([...pageJobs, indexJob, ...tagJobs, rssJob, assetsJob, postPagesSub, tagDirSub]);
}

import { readdir, stat } from "node:fs/promises";

export async function collectFiles(dir: string, ext: string): Promise<string[]> {
  const results: string[] = [];
  const entries = await readdir(dir, { withFileTypes: true }).catch(() => [] as never[]);
  for (const e of entries as { name: string; isDirectory(): boolean }[]) {
    const full = `${dir}/${e.name}`;
    if (e.isDirectory()) {
      const nested = await collectFiles(full, ext);
      results.push(...nested);
    } else if (e.name.endsWith(ext)) {
      results.push(full);
    }
  }
  return results;
}

import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
import { readFile } from "node:fs/promises";
import { join, extname } from "node:path";
import { WebSocketServer } from "ws";
import { watch } from "chokidar";
import type { SiteConfig } from "./types.js";
import { generate } from "./generator.js";

const RELOAD_SCRIPT = `
<script>
(function() {
  var ws = new WebSocket('ws://' + location.host + '/__live_reload');
  ws.onmessage = function(msg) {
    if (msg.data === 'reload') location.reload();
  };
})();
</script>`;

const MIME: Record<string, string> = {
  ".html": "text/html",
  ".css": "text/css",
  ".js": "application/javascript",
  ".json": "application/json",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".svg": "image/svg+xml",
  ".ico": "image/x-icon",
  ".xml": "application/xml",
};

export async function serve(config: SiteConfig, watchMode: boolean): Promise<void> {
  const wss = new WebSocketServer({ noServer: true });

  wss.on("connection", (ws) => {
    ws.on("error", () => {});
  });

  function broadcast() {
    for (const client of wss.clients) {
      if (client.readyState === 1) client.send("reload");
    }
  }

  const server = createServer(async (req: IncomingMessage, res: ServerResponse) => {
    const url = req.url === "/" ? "/index.html" : req.url ?? "/index.html";
    const filePath = join(config.out, url);

    if (url === "/__live_reload") {
      return;
    }

    try {
      let content = await readFile(filePath);
      const ext = extname(filePath);

      if (ext === ".html" && watchMode) {
        content = Buffer.concat([content, Buffer.from(RELOAD_SCRIPT)]);
      }

      res.writeHead(200, { "Content-Type": MIME[ext] ?? "application/octet-stream" });
      res.end(content);
    } catch {
      if (watchMode && url.endsWith(".html")) {
        try {
          const notFound = await readFile(join(config.out, "index.html"));
          let nf = notFound;
          if (watchMode) {
            nf = Buffer.concat([nf, Buffer.from(RELOAD_SCRIPT)]);
          }
          res.writeHead(200, { "Content-Type": "text/html" });
          res.end(nf);
          return;
        } catch {}
      }
      res.writeHead(404);
      res.end("Not found");
    }
  });

  server.on("upgrade", (req, socket, head) => {
    if (req.url === "/__live_reload") {
      wss.handleUpgrade(req, socket, head, (ws) => {
        wss.emit("connection", ws, req);
      });
    } else {
      socket.destroy();
    }
  });

  if (watchMode) {
    const contentWatcher = watch([`${config.src}/**/*.md`, `${config.tmpl}/**/*.{hbs,handlebars}`], {
      ignoreInitial: true,
    });

    const onChange = async () => {
      await generate(config);
      broadcast();
    };

    let debounceTimer: ReturnType<typeof setTimeout>;
    contentWatcher.on("all", () => {
      clearTimeout(debounceTimer);
      debounceTimer = setTimeout(onChange, 100);
    });
  }

  server.listen(config.port, () => {
    console.log(`Server running at http://localhost:${config.port}/`);
  });
}

#!/usr/bin/env node
import { Command } from "commander";
import { resolve } from "node:path";
import { generate } from "./generator.js";
import { serve } from "./server.js";
import type { SiteConfig } from "./types.js";

const program = new Command();

program
  .name("static-site-gen")
  .description("Static site generator from Markdown + Handlebars");

program
  .command("build")
  .description("Build the static site")
  .requiredOption("--src <dir>", "Source directory of markdown files", "content")
  .requiredOption("--tmpl <dir>", "Template directory of handlebars files", "templates")
  .requiredOption("--out <dir>", "Output directory for generated HTML", "public")
  .option("--base-url <url>", "Base URL for RSS feed", "http://localhost:3000")
  .option("--title <title>", "Site title", "My Site")
  .option("--description <desc>", "Site description", "A static site")
  .action(async (opts) => {
    const config: SiteConfig = {
      src: resolve(opts.src),
      tmpl: resolve(opts.tmpl),
      out: resolve(opts.out),
      port: 3000,
      baseUrl: opts.baseUrl,
      title: opts.title,
      description: opts.description,
    };
    await generate(config);
    console.log(`Site built to ${config.out}`);
  });

program
  .command("dev")
  .description("Start dev server with live reload")
  .requiredOption("--src <dir>", "Source directory of markdown files", "content")
  .requiredOption("--tmpl <dir>", "Template directory of handlebars files", "templates")
  .requiredOption("--out <dir>", "Output directory for generated HTML", "public")
  .option("--port <number>", "Port for dev server", "3000")
  .option("--base-url <url>", "Base URL for RSS feed", "http://localhost:3000")
  .option("--title <title>", "Site title", "My Site")
  .option("--description <desc>", "Site description", "A static site")
  .action(async (opts) => {
    const config: SiteConfig = {
      src: resolve(opts.src),
      tmpl: resolve(opts.tmpl),
      out: resolve(opts.out),
      port: parseInt(opts.port, 10),
      baseUrl: opts.baseUrl,
      title: opts.title,
      description: opts.description,
    };
    await generate(config);
    console.log(`Initial build complete. Starting dev server...`);
    await serve(config, true);
  });

program
  .command("serve")
  .description("Serve the output directory")
  .requiredOption("--out <dir>", "Output directory to serve", "public")
  .option("--port <number>", "Port for server", "3000")
  .action(async (opts) => {
    const config: SiteConfig = {
      src: "",
      tmpl: "",
      out: resolve(opts.out),
      port: parseInt(opts.port, 10),
      baseUrl: `http://localhost:${opts.port}`,
      title: "",
      description: "",
    };
    await serve(config, false);
  });

program.parse();

import { describe, it, expect } from "vitest";
import { parseString, parseFile } from "../src/parser.js";
import { resolve } from "node:path";

describe("parseString", () => {
  it("parses yaml frontmatter", () => {
    const md = `---
title: Hello
date: 2024-01-01
tags:
  - a
  - b
---

Content`;
    const { data, content } = parseString(md);
    expect(data.title).toBe("Hello");
    expect(data.date).toBe("2024-01-01");
    expect(data.tags).toEqual(["a", "b"]);
    expect(content.trim()).toBe("Content");
  });

  it("returns empty frontmatter when none present", () => {
    const { data, content } = parseString("Just content");
    expect(data.title).toBeUndefined();
    expect(content.trim()).toBe("Just content");
  });

  it("detects draft status", () => {
    const { data } = parseString("---\ndraft: true\n---\nstuff");
    expect(data.draft).toBe(true);
  });

  it("handles extra custom frontmatter", () => {
    const { data } = parseString("---\ntitle: X\nauthor: Me\n---\nbody");
    expect(data.title).toBe("X");
    expect(data.author).toBe("Me");
  });

  it("handles empty tags", () => {
    const { data } = parseString("---\ntitle: X\ntags:\n---\nbody");
    expect(data.tags).toBeUndefined();
  });
});

describe("parseFile", () => {
  it("parses a real markdown file", async () => {
    const page = await parseFile(resolve("tests/fixtures/content/hello.md"));
    expect(page).not.toBeNull();
    expect(page!.frontmatter.title).toBe("Hello World");
    expect(page!.frontmatter.tags).toEqual(["example", "test"]);
    expect(page!.slug).toBe("hello");
  });

  it("returns null for draft posts", async () => {
    const page = await parseFile(resolve("tests/fixtures/content/draft-post.md"));
    expect(page).toBeNull();
  });

  it("sets correct slug from filename", async () => {
    const page = await parseFile(resolve("tests/fixtures/content/tagged-post.md"));
    expect(page!.slug).toBe("tagged-post");
  });
});

import { describe, it, expect } from "vitest";
import { resolve } from "node:path";
import { loadTemplates, renderMarkdown, renderTemplate } from "../src/renderer.js";

describe("renderMarkdown", () => {
  it("renders basic markdown to HTML", () => {
    const html = renderMarkdown("# Hello\n\nWorld");
    expect(html).toContain("<h1>Hello</h1>");
    expect(html).toContain("<p>World</p>");
  });

  it("renders bold and italic", () => {
    const html = renderMarkdown("**bold** *italic*");
    expect(html).toContain("<strong>bold</strong>");
    expect(html).toContain("<em>italic</em>");
  });

  it("renders links", () => {
    const html = renderMarkdown("[link](http://example.com)");
    expect(html).toContain('<a href="http://example.com">link</a>');
  });

  it("renders fenced code blocks with syntax highlighting", () => {
    const html = renderMarkdown('```js\nconst x = 1;\n```');
    expect(html).toContain("hljs");
    expect(html).toContain("language-js");
    expect(html).toContain("const");
  });

  it("renders code blocks without language", () => {
    const html = renderMarkdown("```\nplain text\n```");
    expect(html).toContain("<code>plain text");
  });

  it("renders lists", () => {
    const html = renderMarkdown("- one\n- two\n- three");
    expect(html).toContain("<ul>");
    expect(html).toContain("<li>one</li>");
    expect(html).toContain("<li>two</li>");
    expect(html).toContain("<li>three</li>");
  });
});

